using System.Diagnostics;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using Jindan.Core.Sync;

internal static class Program
{
 static string root="",work=""; static int pass,fail; static readonly List<object> evidence=[]; static readonly SyncScope Scope=new("synthetic-user-a","synthetic-project-a");
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
 static string Folder(){var p=Path.Combine(work,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
 static SyncRecord Row(string id,string text,string? owner="synthetic-user-a")=>new(id,owner,new JsonObject{["content"]=text});
 static string Text(SyncRecord row)=>row.Fields["content"]!.GetValue<string>();
 static IsolatedLoopbackSyncAdapter Fake(params SyncScope[] scopes)=>new(scopes.Length==0?[Scope]:scopes,true);
 static async Task Expect(string code,Func<Task> action){try{await action();}catch(SyncException e){Assert(e.Code==code,$"Expected {code}, got {e.Code}");return;}throw new Exception("Expected "+code);}
 static async Task Run(string name,Func<Task> action){try{await action();pass++;Console.WriteLine("PASS "+name);evidence.Add(new{name,passed=true});}catch(Exception e){fail++;Console.WriteLine("FAIL "+name+": "+e.GetType().Name+" "+e.Message);evidence.Add(new{name,passed=false,error=e.GetType().Name,message=e.Message});}}
 static async Task Cancelled(Task task){try{await task;}catch(OperationCanceledException){return;}throw new Exception("Expected cancellation");}
 public static async Task<int> Main(string[] args)
 {
  root=AppContext.BaseDirectory;while(!File.Exists(Path.Combine(root,"Directory.Build.props")))root=Path.GetDirectoryName(root)??throw new Exception("Source root missing");
  if(args.FirstOrDefault()=="crash-write"){await new SyncStore(args[1],Scope).UpsertAsync(SyncTable.Projects,Row("after-crash","durable-synthetic"));Environment.Exit(73);return 99;}
  work=Path.Combine(root,"artifacts","sync-tests",DateTime.UtcNow.ToString("yyyyMMddTHHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);
  await Run("production is explicit NotConfigured; loopback requires opt-in",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","local"));await Expect("PRODUCTION_NOT_CONFIGURED",()=>new SyncCoordinator(s,new NotConfiguredSyncAdapter()).SyncAllAsync());await Expect("TEST_FIXTURE_NOT_ENABLED",()=>Task.Run(()=>new IsolatedLoopbackSyncAdapter([Scope],false)));Assert((await s.SnapshotAsync()).Pending.Count==1,"NotConfigured lost pending local work");});
  await Run("cache plus outbox persist atomically and coalesce by record revision",async()=>{var dir=Folder();var s=new SyncStore(dir,Scope);var first=await s.UpsertAsync(SyncTable.Projects,Row("a","one"));var second=await s.UpsertAsync(SyncTable.Projects,Row("a","two"));var snap=await new SyncStore(dir,Scope).SnapshotAsync();Assert(snap.Pending.Count==1&&snap.Pending[0].Revision==second&&first!=second&&Text(snap.Tables[SyncTable.Projects][0])=="two","Latest revision did not survive restart");await s.DeleteAsync(SyncTable.Projects,"a");snap=await s.SnapshotAsync();Assert(snap.Pending.Single().Operation==SyncOperation.Delete&&snap.Tables[SyncTable.Projects].Count==0,"Explicit delete not queued");});
  await Run("mutable caller records and returned snapshots do not mutate stored data",async()=>{var s=new SyncStore(Folder(),Scope);var input=Row("a","original");await s.UpsertAsync(SyncTable.Projects,input);input.Fields["content"]="mutated";var snap=await s.SnapshotAsync();snap.Tables[SyncTable.Projects][0].Fields["content"]="snapshot-mutated";Assert(Text((await s.SnapshotAsync()).Tables[SyncTable.Projects][0])=="original","Input immutability failed");});
  await Run("synthetic push-first full sync acknowledges and marks only test mode",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","value"));var remote=Fake();var result=await new SyncCoordinator(s,remote).SyncAllAsync();Assert(result.Push.Acknowledged==1&&result.PulledTables==3&&result.LastSyncAdvanced&&result.IsSynthetic&&!result.ProductionVerified&&!remote.RealServerAuthorizationVerified&&(await s.SnapshotAsync()).Pending.Count==0,"Synthetic result incorrect");});
  await Run("legacy missing upsert never becomes deletion or silent acknowledgement",async()=>{var s=new SyncStore(Folder(),Scope);await s.QueueLegacyMissingUpsertAsync(SyncTable.Processes,"missing");var remote=Fake();var result=await new SyncCoordinator(s,remote).SyncAllAsync();Assert(remote.DeliveryAttempts==0&&result.Push.SkippedMissing==1&&!result.LastSyncAdvanced&&(await s.SnapshotAsync()).Pending.Count==1,"Missing record became remote operation");});
  await Run("pending local edit wins remote overwrite and explicit remote tombstone",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","pending-local"));var remote=Fake();remote.Seed(Scope,SyncTable.Projects,[Row("a","remote") with{Deleted=true}]);remote.BeforePush=(_,_)=>Task.FromException(new SyncException("OFFLINE"));await new SyncCoordinator(s,remote).SyncAllAsync();var snap=await s.SnapshotAsync();Assert(snap.Pending.Count==1&&Text(snap.Tables[SyncTable.Projects].Single())=="pending-local","Pending local edit lost to pull");});
  await Run("missing projects/processes retained; explicit tombstones remove",async()=>{var s=new SyncStore(Folder(),Scope);foreach(var table in new[]{SyncTable.Projects,SyncTable.Processes}){await s.MergePullAsync(new(Scope,table,[Row("a","old")],true));await s.MergePullAsync(new(Scope,table,[],true));Assert((await s.SnapshotAsync()).Tables[table].Count==1,"Missing non-task inferred deletion");await s.MergePullAsync(new(Scope,table,[Row("a","tombstone") with{Deleted=true}],true));Assert((await s.SnapshotAsync()).Tables[table].Count==0,"Explicit tombstone did not remove");}});
  await Run("task pruning distinguishes owner legacy pending and incomplete snapshots",async()=>{var s=new SyncStore(Folder(),Scope);await s.MergePullAsync(new(Scope,SyncTable.Tasks,[Row("owned","old"),Row("legacy","old",null),Row("pending","old")],true));await s.UpsertAsync(SyncTable.Tasks,Row("pending","local"));await s.MergePullAsync(new(Scope,SyncTable.Tasks,[],false));Assert((await s.SnapshotAsync()).Tables[SyncTable.Tasks].Count==3,"Incomplete response pruned tasks");await s.MergePullAsync(new(Scope,SyncTable.Tasks,[],true));var rows=(await s.SnapshotAsync()).Tables[SyncTable.Tasks];Assert(rows.Count==2&&rows.Any(r=>r.Id=="legacy")&&rows.Any(r=>r.Id=="pending"),"Task prune scope changed");await s.DeleteAsync(SyncTable.Tasks,"pending");await s.MergePullAsync(new(Scope,SyncTable.Tasks,[Row("pending","remote-resurrection")],true));Assert(!(await s.SnapshotAsync()).Tables[SyncTable.Tasks].Any(r=>r.Id=="pending"),"Pending delete resurrected");});
  await Run("wrong revision acknowledgement cannot clear queue",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","local"));var r=Fake();r.RewriteAcknowledgement=a=>a with{Revision=Guid.NewGuid().ToString("N")};var result=await new SyncCoordinator(s,r).PushAsync();Assert(result.Acknowledged==0&&result.Issues.Single().Code=="ACK_MISMATCH"&&(await s.SnapshotAsync()).Pending.Count==1,"Wrong ACK cleared queue");});
  await Run("edit racing old ACK preserves new local revision for later retry",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","one"));var entered=new TaskCompletionSource();var release=new TaskCompletionSource();var r=Fake();r.BeforePush=async(_,ct)=>{entered.SetResult();await release.Task.WaitAsync(ct);};var c=new SyncCoordinator(s,r);var first=c.PushAsync();await entered.Task;var latest=await s.UpsertAsync(SyncTable.Projects,Row("a","two"));release.SetResult();await first;Assert((await s.SnapshotAsync()).Pending.Single().Revision==latest,"Old ACK removed latest queued change");r.BeforePush=null;await c.PushAsync();Assert((await s.SnapshotAsync()).Pending.Count==0&&Text((await r.FetchAsync(Scope,SyncTable.Projects,default)).Records.Single())=="two","Latest retry failed");});
  await Run("partial push succeeds independently and retries only remaining entry",async()=>{var s=new SyncStore(Folder(),Scope);foreach(var id in new[]{"a","b","c"})await s.UpsertAsync(SyncTable.Processes,Row(id,id));var r=Fake();r.BeforePush=(e,_)=>e.Pending.Id=="b"?Task.FromException(new Exception("sensitive body must not escape")):Task.CompletedTask;var c=new SyncCoordinator(s,r);var first=await c.PushAsync();Assert(first.Acknowledged==2&&first.Issues.Single().Code=="REMOTE_ERROR"&&(await s.SnapshotAsync()).Pending.Single().Id=="b","Partial queue retry scope incorrect");r.BeforePush=null;var second=await c.PushAsync();Assert(second.Attempted==1&&second.Acknowledged==1&&r.DeliveryAttempts==4&&r.AppliedMutations==3,"Retry repeated already acknowledged work");});
  await Run("lost ACK survives restart and loopback revision replay is idempotent",async()=>{var dir=Folder();var s=new SyncStore(dir,Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","once"));var r=Fake();r.AfterCommitBeforeAck=(_,_)=>Task.FromException(new IOException("synthetic lost acknowledgement"));await new SyncCoordinator(s,r).PushAsync();Assert((await s.SnapshotAsync()).Pending.Count==1&&r.AppliedMutations==1,"Lost ACK not retained");r.AfterCommitBeforeAck=null;await new SyncCoordinator(new SyncStore(dir,Scope),r).PushAsync();Assert(r.DeliveryAttempts==2&&r.AppliedMutations==1&&(await s.SnapshotAsync()).Pending.Count==0,"Replay was not idempotent");});
  await Run("actual fresh process crash after committed enqueue survives restart",async()=>{var dir=Folder();var info=new ProcessStartInfo(Path.Combine(root,".tools/dotnet/dotnet.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};info.ArgumentList.Add(Assembly.GetExecutingAssembly().Location);info.ArgumentList.Add("crash-write");info.ArgumentList.Add(dir);using var p=Process.Start(info)!;using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(20));try{await p.WaitForExitAsync(timeout.Token);}catch{if(!p.HasExited){p.Kill(true);await p.WaitForExitAsync();}throw;}Assert(p.ExitCode==73,"Owned crash fixture did not exit as requested");var snap=await new SyncStore(dir,Scope).SnapshotAsync();Assert(snap.Pending.Count==1&&snap.Tables[SyncTable.Projects].Single().Id=="after-crash","Committed queue lost across process restart");});
  await Run("simultaneous push requests coalesce to one transport",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","once"));var entered=new TaskCompletionSource();var release=new TaskCompletionSource();var r=Fake();r.BeforePush=async(_,ct)=>{entered.SetResult();await release.Task.WaitAsync(ct);};var c=new SyncCoordinator(s,r);var first=c.PushAsync();await entered.Task;var second=c.PushAsync();Assert(ReferenceEquals(first,second),"Push tasks were not coalesced");release.SetResult();await Task.WhenAll(first,second);Assert(r.DeliveryAttempts==1,"Duplicate push transport");});
  await Run("later waiter cancellation does not abort original coalesced owner",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","once"));var entered=new TaskCompletionSource();var release=new TaskCompletionSource();var r=Fake();r.BeforePush=async(_,ct)=>{entered.SetResult();await release.Task.WaitAsync(ct);};var c=new SyncCoordinator(s,r);var owner=c.PushAsync();await entered.Task;using var ct=new CancellationTokenSource();var waiter=c.PushAsync(ct.Token);ct.Cancel();await Cancelled(waiter);Assert(!owner.IsCompleted,"Secondary cancellation aborted owner");release.SetResult();await owner;Assert((await s.SnapshotAsync()).Pending.Count==0,"Owner did not acknowledge");});
  await Run("owner cancellation preserves unacknowledged queue and permits retry",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","once"));var entered=new TaskCompletionSource();var r=Fake();r.BeforePush=async(_,ct)=>{entered.SetResult();await Task.Delay(Timeout.Infinite,ct);};var c=new SyncCoordinator(s,r);using var ct=new CancellationTokenSource();var attempt=c.PushAsync(ct.Token);await entered.Task;ct.Cancel();await Cancelled(attempt);Assert((await s.SnapshotAsync()).Pending.Count==1&&r.AppliedMutations==0,"Cancellation cleared pending work");r.BeforePush=null;await c.PushAsync();Assert((await s.SnapshotAsync()).Pending.Count==0,"Retry after cancellation failed");});
  await Run("user-project namespaces and foreign pull/ACK remain isolated",async()=>{var dir=Folder();var scopes=new[]{Scope,new SyncScope("synthetic-user-b",Scope.ProjectId),new SyncScope(Scope.UserId,"synthetic-project-b")};var stores=scopes.Select(x=>new SyncStore(dir,x)).ToArray();foreach(var s in stores)await s.UpsertAsync(SyncTable.Projects,Row("same-id",s.Scope.UserId+":"+s.Scope.ProjectId));Assert(stores.Select(s=>s.StateFile).Distinct().Count()==3,"Namespace file collision");var r=Fake(Scope);await Expect("LOOPBACK_SCOPE_DENIED",()=>r.FetchAsync(scopes[1],SyncTable.Projects,default));await Expect("SCOPE_MISMATCH",()=>stores[0].MergePullAsync(new(scopes[1],SyncTable.Projects,[],true)));var snap=await stores[0].SnapshotAsync();var sent=new SyncEnvelope(Scope,snap.Pending[0],snap.Tables[SyncTable.Projects][0]);await Expect("ACK_MISMATCH",()=>stores[0].AcknowledgeAsync(sent,new(scopes[1],sent.Pending.Table,sent.Pending.Id,sent.Pending.Revision,true)));Assert((await stores[0].SnapshotAsync()).Pending.Count==1,"Foreign ACK mutated queue");});
  await Run("duplicate remote records and untrusted error text fail closed",async()=>{var s=new SyncStore(Folder(),Scope);await Expect("REMOTE_DUPLICATE",()=>s.MergePullAsync(new(Scope,SyncTable.Projects,[Row("a","one"),Row("a","two")],true)));await s.UpsertAsync(SyncTable.Projects,Row("a","local"));var r=Fake();r.BeforePush=(_,_)=>Task.FromException(new SyncException("secret document body"));Assert((await new SyncCoordinator(s,r).PushAsync()).Issues.Single().Code=="REMOTE_ERROR","Remote error body escaped through code field");});
  await Run("future schema is preserved and never downgraded using old backup",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","one"));await s.UpsertAsync(SyncTable.Projects,Row("a","two"));var doc=JsonNode.Parse(await File.ReadAllTextAsync(s.StateFile))!.AsObject();doc["schema"]=2;var bytes=doc.ToJsonString();await File.WriteAllTextAsync(s.StateFile,bytes);await Expect("SCHEMA_UNSUPPORTED",()=>s.SnapshotAsync());Assert(await File.ReadAllTextAsync(s.StateFile)==bytes,"Future schema overwritten with backup");});
  await Run("corrupt primary recovers valid backup with explicit flag",async()=>{var dir=Folder();var s=new SyncStore(dir,Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","one"));await s.UpsertAsync(SyncTable.Projects,Row("a","two"));await File.WriteAllTextAsync(s.StateFile,"{broken");var reopened=new SyncStore(dir,Scope);var snap=await reopened.SnapshotAsync();Assert(reopened.RecoveredFromBackup&&Text(snap.Tables[SyncTable.Projects].Single())=="one"&&Directory.GetFiles(dir,"*.corrupt-*").Length==1,"Validated backup recovery missing evidence");});
  await Run("multiple store instances serialize the same namespace without lost updates",async()=>{var dir=Folder();var stores=new[]{new SyncStore(dir,Scope),new SyncStore(dir,Scope)};await Parallel.ForEachAsync(Enumerable.Range(0,16),new ParallelOptions{MaxDegreeOfParallelism=4},async(i,ct)=>await stores[i%2].UpsertAsync(SyncTable.Processes,Row("row-"+i,i.ToString()),ct));var snapshot=await new SyncStore(dir,Scope).SnapshotAsync();Assert(snapshot.Pending.Count==16&&snapshot.Tables[SyncTable.Processes].Count==16,"Cross-instance store lease lost local mutations");});
  await Run("partial pull failure does not advance last-sync and pull does not enqueue writes",async()=>{var s=new SyncStore(Folder(),Scope);var r=Fake();r.Seed(Scope,SyncTable.Projects,[Row("remote","remote-only")]);r.BeforeFetch=(_,table,_)=>table==SyncTable.Processes?Task.FromException(new IOException("synthetic failure")):Task.CompletedTask;var result=await new SyncCoordinator(s,r).SyncAllAsync();var snapshot=await s.SnapshotAsync();Assert(result.PulledTables==2&&!result.LastSyncAdvanced&&snapshot.LastSuccessfulSync is null&&snapshot.Pending.Count==0&&snapshot.Tables[SyncTable.Projects].Count==1,"Partial pull advanced completion or created upload echo");});
  await Run("store lease wait honors cancellation without changing committed bytes",async()=>{var s=new SyncStore(Folder(),Scope);await s.UpsertAsync(SyncTable.Projects,Row("a","one"));var before=await File.ReadAllBytesAsync(s.StateFile);using(var lease=new FileStream(s.StateFile+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){using var ct=new CancellationTokenSource(100);await Cancelled(s.UpsertAsync(SyncTable.Projects,Row("a","two"),ct.Token));}var after=await File.ReadAllBytesAsync(s.StateFile);Assert(before.AsSpan().SequenceEqual(after),"Cancelled lock wait changed state");});
  await Run("record depth/size/table inputs are bounded before mutation",async()=>{var s=new SyncStore(Folder(),Scope);await Expect("RECORD_LIMIT",()=>s.UpsertAsync(SyncTable.Projects,Row("large",new string('x',600001))));await Expect("TABLE_INVALID",()=>s.DeleteAsync((SyncTable)999,"a"));Assert(!File.Exists(s.StateFile),"Rejected bounded input created data state");});
  var result=new{roadmap="66",pass,fail,work,networkCalls=0,productionAdapter="NotConfigured",liveAuthorizationVerified=false,productIntegration="not-connected-by-design",reportReady=false,supervisorAccepted=false,tests=evidence};await File.WriteAllTextAsync(Path.Combine(work,"RESULT.json"),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"SYNC_TESTS pass={pass} fail={fail} evidence={work}");return fail==0?0:1;
 }
}

